-- Staging-only finance posting link table.
CREATE TABLE IF NOT EXISTS pipe_finance_postings (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, organization_id INTEGER NOT NULL REFERENCES organizations(id), source_type TEXT NOT NULL, source_id BIGINT NOT NULL, voucher_id BIGINT NOT NULL, posted_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(organization_id,source_type,source_id), UNIQUE(organization_id,voucher_id), FOREIGN KEY(organization_id,voucher_id) REFERENCES vouchers(organization_id,id));
